#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int n, k, p;
int64 target;
vector<int> a;
vector<int64> factorialValue;
vector<vector<int64>> rightSums;

void generateRight(int index, int64 sum, int used) {
    if (sum > target || used > k) return;

    if (index == n) {
        rightSums[used].push_back(sum);
        return;
    }

    generateRight(index + 1, sum, used);
    generateRight(index + 1, sum + a[index], used);

    if (a[index] >= 0 && a[index] <= p) {
        generateRight(index + 1, sum + factorialValue[a[index]], used + 1);
    }
}

int64 answer = 0;
int leftEnd;

void generateLeft(int index, int64 sum, int used) {
    if (sum > target || used > k) return;

    if (index == leftEnd) {
        const int64 needed = target - sum;
        for (int d = 0; d + used <= k && d < (int)rightSums.size(); ++d) {
            const auto range = equal_range(
                rightSums[d].begin(), rightSums[d].end(), needed
            );
            answer += range.second - range.first;
        }
        return;
    }

    generateLeft(index + 1, sum, used);
    generateLeft(index + 1, sum + a[index], used);

    if (a[index] >= 0 && a[index] <= p) {
        generateLeft(index + 1, sum + factorialValue[a[index]], used + 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> target;
    a.resize(n);
    for (int &x : a) cin >> x;

    factorialValue.assign(21, 0);
    factorialValue[0] = factorialValue[1] = 1;
    p = (target >= 1 ? 1 : 0);

    for (int i = 2; i < (int)factorialValue.size(); ++i) {
        if (factorialValue[i - 1] > target / i) break;
        factorialValue[i] = factorialValue[i - 1] * i;
        p = i;
    }

    leftEnd = n / 2;
    const int rightCount = n - leftEnd;
    const int maxUsed = min(k, rightCount);

    rightSums.resize(maxUsed + 1);

    int eligible = 0;
    for (int i = leftEnd; i < n; ++i) {
        if (a[i] >= 0 && a[i] <= p) ++eligible;
    }

    vector<unsigned long long> combination(eligible + 1, 0);
    combination[0] = 1;
    for (int i = 1; i <= eligible; ++i) {
        combination[i] = combination[i - 1] * (eligible - i + 1) / i;
    }

    for (int d = 0; d <= maxUsed && d <= eligible; ++d) {
        const unsigned long long capacity =
            combination[d] * (1ULL << (rightCount - d));
        rightSums[d].reserve(static_cast<size_t>(capacity));
    }

    generateRight(leftEnd, 0, 0);

    for (auto &values : rightSums) {
        sort(values.begin(), values.end());
    }

    generateLeft(0, 0, 0);
    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    long long x;
    int d;

    bool operator<(const Node& other) const {
        if (x != other.x) return x < other.x;
        return d < other.d;
    }
};

int n, k, p;
int a[30];
long long s, fact[30], ans;
vector<Node> rightHalf;

void generateRight(int pos, long long sum, int used) {
    if (sum > s) return;
    if (pos > n) {
        rightHalf.push_back({sum, used});
        return;
    }

    generateRight(pos + 1, sum, used);

    if (a[pos] <= s - sum)
        generateRight(pos + 1, sum + a[pos], used);

    if (a[pos] <= p && fact[a[pos]] <= s - sum)
        generateRight(pos + 1, sum + fact[a[pos]], used + 1);
}

long long countRight(long long target, int maxUsed) {
    if (target < 0 || maxUsed < 0) return 0;

    Node low{target, -1};
    Node high{target, maxUsed};

    auto first = lower_bound(rightHalf.begin(), rightHalf.end(), low);
    auto last = upper_bound(rightHalf.begin(), rightHalf.end(), high);

    return last - first;
}

void generateLeft(int pos, int end, long long sum, int used) {
    if (sum > s || used > k) return;
    if (pos > end) {
        ans += countRight(s - sum, k - used);
        return;
    }

    generateLeft(pos + 1, end, sum, used);

    if (a[pos] <= s - sum)
        generateLeft(pos + 1, end, sum + a[pos], used);

    if (a[pos] <= p && fact[a[pos]] <= s - sum)
        generateLeft(pos + 1, end, sum + fact[a[pos]], used + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> s;
    for (int i = 1; i <= n; ++i) cin >> a[i];

    fact[0] = fact[1] = 1;
    p = 1;
    for (int i = 2; i < 30; ++i) {
        if (fact[i - 1] > s / i) {
            p = i - 1;
            break;
        }
        fact[i] = fact[i - 1] * i;
        if (fact[i] > s) {
            p = i - 1;
            break;
        }
        p = i;
    }

    int mid = n / 2;

    size_t capacity = 1;
    for (int i = mid + 1; i <= n; ++i) capacity *= 3;
    rightHalf.reserve(capacity);

    generateRight(mid + 1, 0, 0);
    sort(rightHalf.begin(), rightHalf.end());

    generateLeft(1, mid, 0, 0);

    cout << ans;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, k, splitPoint;
long long s;
int a[35];
long long factValue[35];

#pragma pack(push, 1)
struct Node {
    long long sum;
    unsigned char used;
};
#pragma pack(pop)

vector<Node> rightStates;
long long answer = 0;

long long readLongLong() {
    int ch = getchar();
    while (ch != EOF && ch != '-' && !isdigit(ch)) ch = getchar();

    long long sign = 1, value = 0;
    if (ch == '-') {
        sign = -1;
        ch = getchar();
    }

    while (ch != EOF && isdigit(ch)) {
        value = value * 10 + (ch - '0');
        ch = getchar();
    }
    return value * sign;
}

void generateRight(int pos, long long sum, int used) {
    if (pos > splitPoint) {
        rightStates.push_back({sum, static_cast<unsigned char>(used)});
        return;
    }

    generateRight(pos + 1, sum, used);

    if (a[pos] >= 0 && static_cast<long long>(a[pos]) <= s - sum)
        generateRight(pos + 1, sum + a[pos], used);

    if (a[pos] >= 0 && a[pos] < 35 && factValue[a[pos]] != -1 &&
        factValue[a[pos]] <= s - sum)
        generateRight(pos + 1, sum + factValue[a[pos]], used + 1);
}

struct NodeLess {
    bool operator()(const Node& lhs, const Node& rhs) const {
        if (lhs.sum != rhs.sum) return lhs.sum < rhs.sum;
        return lhs.used < rhs.used;
    }
};

long long countRight(long long target, int maxUsed) {
    if (maxUsed < 0) return 0;
    maxUsed = min(maxUsed, 255);

    Node low{target, 0};
    Node high{target, static_cast<unsigned char>(maxUsed)};

    auto first = lower_bound(rightStates.begin(), rightStates.end(), low, NodeLess{});
    auto last = upper_bound(rightStates.begin(), rightStates.end(), high, NodeLess{});
    return last - first;
}

void generateLeft(int pos, long long sum, int used) {
    if (pos > n) {
        answer += countRight(s - sum, k - used);
        return;
    }

    generateLeft(pos + 1, sum, used);

    if (a[pos] >= 0 && static_cast<long long>(a[pos]) <= s - sum)
        generateLeft(pos + 1, sum + a[pos], used);

    if (a[pos] >= 0 && a[pos] < 35 && factValue[a[pos]] != -1 &&
        factValue[a[pos]] <= s - sum)
        generateLeft(pos + 1, sum + factValue[a[pos]], used + 1);
}

int main() {
    n = static_cast<int>(readLongLong());
    k = static_cast<int>(readLongLong());
    s = readLongLong();

    fill(begin(factValue), end(factValue), -1);
    factValue[0] = 1;

    for (int i = 1; i < 35; ++i) {
        if (factValue[i - 1] > s / i) break;
        factValue[i] = factValue[i - 1] * i;
    }

    for (int i = 1; i <= n; ++i)
        a[i] = static_cast<int>(readLongLong());

    splitPoint = n / 2;

    size_t capacity = 1;
    for (int i = 0; i < splitPoint; ++i) capacity *= 3;
    rightStates.reserve(capacity);

    generateRight(1, 0, 0);
    sort(rightStates.begin(), rightStates.end(), NodeLess{});
    generateLeft(splitPoint + 1, 0, 0);

    printf("%lld\n", answer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    int64 s;
    cin >> n >> k >> s;

    vector<int64> a(n);
    for (int64 &x : a) cin >> x;

    vector<int64> factorial(21, 1);
    for (int i = 1; i <= 20; ++i)
        factorial[i] = factorial[i - 1] * i;

    int mid = n / 2;
    vector<vector<int64>> left(k + 1), right(k + 1);

    auto generate = [&](auto &&self, int pos, int end, int used,
                        int64 sum, vector<vector<int64>> &values) -> void {
        if (sum > s || used > k) return;
        if (pos == end) {
            values[used].push_back(sum);
            return;
        }

        self(self, pos + 1, end, used, sum, values);

        if (a[pos] <= s - sum)
            self(self, pos + 1, end, used, sum + a[pos], values);

        if (a[pos] >= 0 && a[pos] <= 20) {
            int64 f = factorial[static_cast<int>(a[pos])];
            if (used < k && f <= s - sum)
                self(self, pos + 1, end, used + 1, sum + f, values);
        }
    };

    generate(generate, 0, mid, 0, 0, left);
    generate(generate, mid, n, 0, 0, right);

    for (auto &v : right)
        sort(v.begin(), v.end());

    int64 answer = 0;
    for (int usedLeft = 0; usedLeft <= k; ++usedLeft) {
        for (int64 leftSum : left[usedLeft]) {
            int64 target = s - leftSum;
            for (int usedRight = 0;
                 usedRight + usedLeft <= k;
                 ++usedRight) {
                const auto &v = right[usedRight];
                auto range = equal_range(v.begin(), v.end(), target);
                answer += distance(range.first, range.second);
            }
        }
    }

    cout << answer;
    return 0;
}

